mapper.insert:
INSERT INTO tax_tuishui_all_qfsd (user_name, id_card, phone, pre_deduct, actual_pay, diff_amount, tax_area, merchant, channel, sale, customer_service) SELECT MAX(vy.payee) AS user_name, vy.id_card, MAX(NULLIF(vy.phone, '')) AS phone, COALESCE(SUM(vy.tax_amount), 0) AS pre_deduct, COALESCE(MAX(yi.total_paid_amount), 0) AS actual_pay, COALESCE(SUM(vy.tax_amount), 0) - COALESCE(MAX(yi.total_paid_amount), 0) AS diff_amount, vy.tax_area, GROUP_CONCAT(DISTINCT NULLIF(vy.merchant, '') ORDER BY vy.merchant SEPARATOR ',') AS merchant, GROUP_CONCAT(DISTINCT NULLIF(vy.channel, '') ORDER BY vy.channel SEPARATOR ',') AS channel, GROUP_CONCAT(DISTINCT NULLIF(vy.sale, '') ORDER BY vy.sale SEPARATOR ',') AS sale, GROUP_CONCAT(DISTINCT NULLIF(vy.customer_service, '') ORDER BY vy.customer_service SEPARATOR ',') AS customer_service FROM v_yukou_all vy LEFT JOIN ( SELECT id_card, tax_area, COALESCE(SUM(paid_amount), 0) AS total_paid_amount FROM yijiao_info_qfsd GROUP BY id_card, tax_area ) yi ON vy.id_card = yi.id_card AND vy.tax_area = yi.tax_area WHERE vy.id_card IN
#{idCard}
GROUP BY vy.id_card, vy.tax_area

INSERT INTO tax_tuishui_all_qfsd (user_name, id_card, phone, pre_deduct, actual_pay, diff_amount, tax_area, merchant, channel, sale, customer_service) SELECT MAX(yi.user_name) AS user_name, yi.id_card, '' AS phone, 0 AS pre_deduct, yi.total_paid_amount AS actual_pay, -yi.total_paid_amount AS diff_amount, yi.tax_area, '' AS merchant, '' AS channel, '' AS sale, '' AS customer_service FROM ( SELECT id_card, tax_area, MAX(user_name) AS user_name, COALESCE(SUM(paid_amount), 0) AS total_paid_amount FROM yijiao_info_qfsd GROUP BY id_card, tax_area ) yi LEFT JOIN v_yukou_all vy_match ON yi.id_card = vy_match.id_card AND yi.tax_area = vy_match.tax_area WHERE vy_match.id_card IS NULL AND yi.id_card IN
#{idCard}
GROUP BY yi.id_card, yi.tax_area
